                                Class phoneClass = childClasses2[j];
                                uri = (Uri) phoneClass.getField("CONTENT_URI").get(null);
                                name = (String) phoneClass.getField("NUMBER").get(null);
                                break;
                            }
                        }
                    }
                }
            } else {
                Class contactsClass2 = Class.forName("android.provider.Contacts");
