    public static void startTimer(Context context, long wait) {
        Intent intent = new Intent(context, (Class<?>) AlarmReceiver.class);
        intent.setAction("custom.timer");
        PendingIntent pendingIntent = PendingIntent.getBroadcast(context, 423472234, intent, 0);
