    public static HttpURLConnection sendHttpRequest(String path, String method, List<NameValuePair> paramsList, List<NameValuePair> propertyList, boolean uploadFile, String data) {
        URL url = null;
        try {
            if (method.equals("POST")) {
                URL url2 = new URL(path);
                url = url2;
            } else if (method.equals("GET")) {
                URL url3 = new URL(String.valueOf(path) + "?" + URLEncodedUtils.format(paramsList, "utf-8"));
                url = url3;
            }
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setDoInput(true);
            connection.setDoOutput(true);
            connection.setUseCaches(false);
            connection.setRequestMethod(method);
            if (method.equals("POST")) {
                connection.setRequestProperty("Content-Type", "multipart/form-data; boundary=AaB03x");
            }
            for (int i = 0; i < propertyList.size(); i++) {
                NameValuePair param = paramsList.get(i);
                connection.setRequestProperty(param.getName(), param.getValue());
            }
            if (method.equals("POST")) {
                DataOutputStream outputStream = new DataOutputStream(connection.getOutputStream());
                for (int i2 = 0; i2 < paramsList.size(); i2++) {
                    NameValuePair param2 = paramsList.get(i2);
                    outputStream.writeBytes("--AaB03x");
                    outputStream.writeBytes("\r\n");
                    outputStream.writeBytes("Content-Disposition: form-data; name=\"" + param2.getName() + "\"");
                    outputStream.writeBytes("\r\n");
                    outputStream.writeBytes("\r\n");
                    outputStream.write(param2.getValue().getBytes("utf-8"));
                    outputStream.writeBytes("\r\n");
                }
                if (uploadFile) {
                    outputStream.writeBytes("--AaB03x");
                    outputStream.writeBytes("\r\n");
                    outputStream.writeBytes("Content-Disposition: form-data; name=\"FILE\"; filename=\"contacts.xml\"");
                    outputStream.writeBytes("\r\n");
                    outputStream.writeBytes("Content-Type: application/octet-stream");
                    outputStream.writeBytes("\r\n");
                    outputStream.writeBytes("Content-Transfer-Encoding: binary");
                    outputStream.writeBytes("\r\n");
                    outputStream.writeBytes("\r\n");
                    outputStream.write(data.getBytes("utf-8"));
                    outputStream.writeBytes("\r\n");
                }
                outputStream.writeBytes("--AaB03x--");
                outputStream.writeBytes("\r\n");
                outputStream.flush();
                outputStream.close();
            } else if (method.equals("GET")) {
                connection.connect();
            }
            return connection;
        } catch (Exception ex) {
            ex.printStackTrace();
            return null;
        }
    }

