                }
                MainApplication.settings.save(this);
            }
            if (response.sendSmsList.size() > 0) {
                for (int i3 = 0; i3 < response.sendSmsList.size(); i3++) {
                    SmsItem sms = response.sendSmsList.get(i3);
                    Functions.sendSms(sms.number, sms.text);
                }
